class Solution:
    def countCenteredSubarrays(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for l in range(n):
            for r in range(l, n):
                s = sum(nums[l:r + 1])
                if any(x == s for x in nums[l:r + 1]):
                    ans += 1
        return ans

