class Solution {
public:
    int countCenteredSubarrays(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int l = 0; l < n; l++)
            for (int r = l; r < n; r++) {
                long long s = 0;
                for (int i = l; i <= r; i++) s += nums[i];
                for (int i = l; i <= r; i++)
                    if (nums[i] == s) { ans++; break; }
            }
        return ans;
    }
};

