class Solution {
    public int countCenteredSubarrays(int[] nums) {
        int n = nums.length, ans = 0;
        for (int l = 0; l < n; l++) {
            long s = 0;
            Set<Long> seen = new HashSet<>();
            for (int r = l; r < n; r++) {
                s += nums[r];
                seen.add((long) nums[r]);
                if (seen.contains(s)) ans++;
            }
        }
        return ans;
    }
}

